SELECT t0.sym AS "Symbol",t1.ID AS "Account Id" FROM trading.trades AS t0 LEFT OUTER JOIN ref_data.account_master AS t1 ON (t1.ID = t0.account_id) WHERE t1.ACCT_NAME = 'Acme Corp' AND t0.in_z <= '2021-06-01 12:00:00' AND (t0.out_z > '2021-06-01 12:00:00' OR t0.out_z IS NULL) ORDER BY t0.sym ASC NULLS FIRST
